INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_WEL_DYLAN_MABINO','ENT_WEL_DYLAN','SRC_MABINOGION','The Mabinogion','The Mabinogion','"Verily," said Math the son of Mathonwy, concerning the fine yellow-haired boy, "I will cause this one to be baptized, and Dylan is the name I will give him." So they had the boy baptized, and as they baptized him he plunged into the sea. And immediately when he was in the sea, he took its nature, and swam as well as the best fish that was therein. And for that reason was he called Dylan, the son of the Wave.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_AMAETHON_MABINO','ENT_WEL_AMAETHON','SRC_MABINOGION','The Mabinogion','The Mabinogion','No husbandman can till or prepare this land, so wild is it, except Amaethon the son of Don, and he will not come with thee by his own free will, and thou wilt not be able to compel him." "It will be easy for me to compass this, although thou mayest think that it will not be easy." "Though thou get this, there is yet that which thou wilt not get.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_ARAWN_MABINO','ENT_WEL_ARAWN','SRC_MABINOGION','The Mabinogion','The Mabinogion','Each claimeth of the other his land and territory, and do all of you stand aside and leave the fight to be between them." Thereupon the two kings approached each other in the middle of the Ford, and encountered, and at the first thrust, the man who was in the stead of Arawn struck Havgan on the centre of the boss of his shield, so that it was cloven in twain, and his armour was broken, and Havgan himself was borne to the groun','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_BLODEUWEDD_MABINO','ENT_WEL_BLODEUWEDD','SRC_MABINOGION','The Mabinogion','The Mabinogion','And they baptized her, and gave her the name of Blodeuwedd. After she had become his bride, and they had feasted, said Gwydion, "It is not easy for a man to maintain himself without possessions." "Of a truth," said Math, "I will give the young man the best Cantrev to hold." "Lord," said he, "what Cantrev is that?" "The Cantrev of Dinodig," he answered. Now it is called at this day Eivionydd and Ardudwy.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_BRANWEN_MABINO','ENT_WEL_BRANWEN','SRC_MABINOGION','The Mabinogion','The Mabinogion','And Branwen was the eighth with them, and they came to land at Aber Alaw, in Talebolyon, and they sat down to rest. And Branwen looked towards Ireland and towards the Island of the Mighty, to see if she could descry them. "Alas," said she, "woe is me that I was ever born; two islands have been destroyed because of me!" Then she uttered a loud groan, and there broke her heart.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_CREIDDYLAD_MABINO','ENT_WEL_CREIDDYLAD','SRC_MABINOGION','The Mabinogion','The Mabinogion','Creiddylad the daughter of Lludd Llaw Ereint. (She was the most splendid maiden in the three Islands of the mighty, and in the three Islands adjacent, and for her Gwythyr the son of Greidawl and Gwynn the son of Nudd fight every first of May until the day of doom.) Ellylw the daughter of Neol Kynn-Crog (she lived three ages).','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_CREIRWY_MABINO','ENT_WEL_CREIRWY','SRC_MABINOGION','The Mabinogion','The Mabinogion','And there was born to him of his wife a son named Morvran ab Tegid, and also a daughter named Creirwy, the fairest maiden in the world was she; and they had a brother, the most ill-favoured man in the world, Avagddu. Now Caridwen his mother thought that he was not likely to be admitted among men of noble birth, by reason of his ugliness, unless he had some exalted merits or knowledge.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GWYDION_MABINO','ENT_WEL_GWYDION','SRC_MABINOGION','The Mabinogion','The Mabinogion','Pryderi dispatched unto Math an embassy to pray him to forbid his people, and to leave it between him and Gwydion the son of Don, for that he had caused all this. And the messengers came to Math. "Of a truth," said Math, "I call Heaven to witness, if it be pleasing unto Gwydion the son of Don, I will so leave it gladly.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GWYN_AP_NUDD_MABINO','ENT_WEL_GWYN_AP_NUDD','SRC_MABINOGION','The Mabinogion','The Mabinogion','When Arthur heard of this, he went to the North, and summoned Gwyn ap Nudd before him, and set free the nobles whom he had put in prison, and made peace between Gwyn ap Nudd and Gwythyr the son of Griedawl.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_GWYTHYR_MABINO','ENT_WEL_GWYTHYR','SRC_MABINOGION','The Mabinogion','The Mabinogion','I seek it from Kai, and Bedwyr, and Greidawl Galldonyd, and Gwythyr the son of Greidawl, and Greid the son of Eri, and Kynddelig Kyvarwydd, and Tathal Twyll Goleu, and Maelwys the son of Baeddan, and Crychwr the son of Nes, and Cubert the son of Daere, and Percos the son of Poch, and Lluber Beuthach, and Corvil Bervach, and Gwynn the son of Nudd, and Edeyrn the son of Nudd, and Gadwy the son of Geraint, and Prince Fflewddur Ff','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_LLEU_LLAW_GYFFES_MABINO','ENT_WEL_LLEU_LLAW_GYFFES','SRC_MABINOGION','The Mabinogion','The Mabinogion','And Gwydion sang another Englyn:- "Oak that grows in upland ground, Is it not wetted by the rain? Has it not been drenched By nine score tempests? It bears in its branches Llew Llaw Gyffes!" Then the eagle came down until he was on the lowest branch of the tree, and thereupon this Englyn did Gwydion sing:- "Oak that grows beneath the steep; Stately and majestic is its aspect! Shall I not speak it? That Llew will come to my lap','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_LLUDD_MABINO','ENT_WEL_LLUDD','SRC_MABINOGION','The Mabinogion','The Mabinogion','THE MABINOGION TRANSLATED BY LADY CHARLOTTE GUEST CONTENTS Introduction The Lady of the Fountain Peredur the Son of Evrawc Geraint the son of Erbin Kilhwch and Olwen The dream of Rhonabwy Pwyll Prince of Dyved Branwen the daughter of Llyr Manawyddan the son of Llyr Math the son of Mathonwy The dream of Maxen Wledig The story of Lludd and Llevelys Taliesin INTRODUCTION Whilst engaged on the Translations contained in these volum','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_LLWYD_MABINO','ENT_WEL_LLWYD','SRC_MABINOGION','The Mabinogion','The Mabinogion','The subject is one not unworthy of the talents of a Llwyd or a Prichard. It might, I think, be shown, by pursuing the inquiry, that the Cymric nation is not only, as Dr.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MABON_MABINO','ENT_WEL_MABON','SRC_MABINOGION','The Mabinogion','The Mabinogion','Say, knowest thou aught of Mabon the son of Modron, who was taken from his mother when three nights old?" The Stag said, "When first I came hither, there was a plain all around me, without any trees save one oak sapling, which grew up to be an oak with an hundred branches.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MATH_MABINO','ENT_WEL_MATH','SRC_MABINOGION','The Mabinogion','The Mabinogion','MATH THE SON OF MATHONWY THIS IS THE FOURTH PORTION OF THE MABINOGI Math the son of Mathonwy was lord over Gwynedd, and Pryderi the son of Pwyll was lord over the one-and-twenty Cantrevs of the South; and these were the seven Cantrevs of Dyved, and the seven Cantrevs of Morganwc, the four Cantrevs of Ceredigiawn, and the three of Ystrad Tywi.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_WEL_MODRON_MABINO','ENT_WEL_MODRON','SRC_MABINOGION','The Mabinogion','The Mabinogion','Say, knowest thou aught of Mabon the son of Modron, who was taken from his mother when three nights old?" The Stag said, "When first I came hither, there was a plain all around me, without any trees save one oak sapling, which grew up to be an oak with an hundred branches.','Lady Charlotte Guest',1877,'https://www.gutenberg.org/ebooks/5160',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work; verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
